using System.Net;
using CvJdAPI.Endpoints;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Xunit;

namespace CvJdAPI.Tests;

public class ExtractCvKeywordTests
{
    [Fact(DisplayName = "FUNC024-USR-UTCID01")] public async Task Ai_success_stores_extracted_cv_keywords() { var dir = Temp(); try { await using var db = ViewCurrentCvTests.CreateDb(); var json = "{\"skills\":[\"C#\",\"SQL\"]}"; Assert.Equal(200, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("cv.pdf"), Guid.NewGuid().ToString(), db, Factory(HttpStatusCode.OK, json), Config(dir)))); var cv = Assert.Single(db.Cvs); Assert.Equal(json, cv.ParsedJson); Assert.Equal("Parsed", cv.ParseStatus); } finally { Directory.Delete(dir, true); } }
    [Fact(DisplayName = "FUNC024-USR-UTCID02")] public async Task Invalid_user_format_prevents_extraction_call() { var dir = Temp(); try { var handler = new CountingHandler(HttpStatusCode.OK, "{}"); await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(400, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("cv.pdf"), "invalid-format", db, new FactoryStub(new HttpClient(handler)), Config(dir)))); Assert.Equal(0, handler.Calls); } finally { Directory.Delete(dir, true); } }
    [Fact(DisplayName = "FUNC024-USR-UTCID03")] public async Task Missing_file_prevents_extraction() { var dir = Temp(); try { var handler = new CountingHandler(HttpStatusCode.OK, "{}"); await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(400, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(null, Guid.NewGuid().ToString(), db, new FactoryStub(new HttpClient(handler)), Config(dir)))); Assert.Equal(0, handler.Calls); } finally { Directory.Delete(dir, true); } }
    [Fact(DisplayName = "FUNC024-USR-UTCID04")] public async Task Ai_rejection_marks_cv_parse_failed() { var dir = Temp(); try { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("cv.pdf"), Guid.NewGuid().ToString(), db, Factory(HttpStatusCode.UnprocessableEntity, "bad"), Config(dir)))); var cv = Assert.Single(db.Cvs); Assert.Null(cv.ParsedJson); Assert.Equal("Failed", cv.ParseStatus); } finally { Directory.Delete(dir, true); } }
    [Fact(DisplayName = "FUNC024-USR-UTCID05")] public async Task Accepted_extension_boundaries_are_sent_for_extraction() { var dir = Temp(); try { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("first.doc"), Guid.NewGuid().ToString(), db, Factory(), Config(dir)))); Assert.Equal(200, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("last.docx"), Guid.NewGuid().ToString(), db, Factory(), Config(dir)))); Assert.Equal(new[] { "doc", "docx" }, db.Cvs.Select(x => x.FileType).OrderBy(x => x).ToArray()); } finally { Directory.Delete(dir, true); } }
    [Fact(DisplayName = "FUNC024-USR-UTCID06")] public async Task Ai_transport_exception_is_safely_recorded_as_failed_parse() { var dir = Temp(); try { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await CvEndpoints.UploadCvAsync(File("cv.pdf"), Guid.NewGuid().ToString(), db, new FactoryStub(new HttpClient(new ThrowingHandler())), Config(dir)))); Assert.Equal("Failed", Assert.Single(db.Cvs).ParseStatus); } finally { Directory.Delete(dir, true); } }

    internal static IFormFile File(string name) { var stream = new MemoryStream(new byte[32]); return new FormFile(stream, 0, 32, "file", name) { Headers = new HeaderDictionary(), ContentType = "application/pdf" }; }
    internal static string Temp() { var path = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString()); Directory.CreateDirectory(path); return path; }
    internal static IConfiguration Config(string dir) => new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string, string?> { ["CV_UPLOADS_PATH"] = dir, ["AI_SERVICE_URL"] = "http://ai" }).Build();
    internal static IHttpClientFactory Factory(HttpStatusCode status = HttpStatusCode.OK, string body = "{}") => new FactoryStub(new HttpClient(new CountingHandler(status, body)));
    internal sealed class FactoryStub(HttpClient client) : IHttpClientFactory { public HttpClient CreateClient(string name) => client; }
    internal sealed class CountingHandler(HttpStatusCode status, string body) : HttpMessageHandler { public int Calls { get; private set; } protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) { Calls++; return Task.FromResult(new HttpResponseMessage(status) { Content = new StringContent(body) }); } }
    internal sealed class ThrowingHandler : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) => throw new HttpRequestException("offline"); }
}

public class ExtractJdKeywordTests
{
    [Fact(DisplayName = "FUNC025-USR-UTCID01")] public async Task Ai_success_stores_extracted_jd_keywords() { await using var db = ViewCurrentCvTests.CreateDb(); var json = "{\"required_skills\":[\"C#\"]}"; Assert.Equal(200, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), "backend", "Dev", "ai", db, Factory(HttpStatusCode.OK, json), Config()))); Assert.Equal(json, Assert.Single(db.JobDescriptions).ClarifiedJson); }
    [Fact(DisplayName = "FUNC025-USR-UTCID02")] public async Task Invalid_user_format_prevents_extraction_call() { await using var db = ViewCurrentCvTests.CreateDb(); var handler = new ExtractCvKeywordTests.CountingHandler(HttpStatusCode.OK, "{}"); Assert.Equal(400, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync("invalid-format", "text", null, "ai", db, new ExtractCvKeywordTests.FactoryStub(new HttpClient(handler)), Config()))); Assert.Equal(0, handler.Calls); }
    [Fact(DisplayName = "FUNC025-USR-UTCID03")] public async Task Empty_jd_text_prevents_extraction() { await using var db = ViewCurrentCvTests.CreateDb(); var handler = new ExtractCvKeywordTests.CountingHandler(HttpStatusCode.OK, "{}"); Assert.Equal(400, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), "", null, "ai", db, new ExtractCvKeywordTests.FactoryStub(new HttpClient(handler)), Config()))); Assert.Equal(0, handler.Calls); }
    [Fact(DisplayName = "FUNC025-USR-UTCID04")] public async Task Ai_rejection_leaves_clarified_json_empty() { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), "text", null, "ai", db, Factory(HttpStatusCode.BadRequest, "bad"), Config()))); Assert.Null(Assert.Single(db.JobDescriptions).ClarifiedJson); }
    [Fact(DisplayName = "FUNC025-USR-UTCID05")] public async Task Text_length_boundaries_are_forwarded_and_persisted() { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), "x", null, "ai", db, Factory(), Config()))); Assert.Equal(200, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), new string('x', 10000), null, "ai", db, Factory(), Config()))); Assert.Equal(new[] { 1, 10000 }, db.JobDescriptions.Select(x => x.RawText.Length).OrderBy(x => x).ToArray()); }
    [Fact(DisplayName = "FUNC025-USR-UTCID06")] public async Task Ai_transport_exception_is_safely_recorded_without_clarified_json() { await using var db = ViewCurrentCvTests.CreateDb(); Assert.Equal(200, ViewCurrentCvTests.Status(await JdEndpoints.SaveJdAsync(Guid.NewGuid().ToString(), "text", null, "ai", db, new ExtractCvKeywordTests.FactoryStub(new HttpClient(new ExtractCvKeywordTests.ThrowingHandler())), Config()))); Assert.Null(Assert.Single(db.JobDescriptions).ClarifiedJson); }
    private static IConfiguration Config() => new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string, string?> { ["AI_SERVICE_URL"] = "http://ai" }).Build();
    private static IHttpClientFactory Factory(HttpStatusCode status = HttpStatusCode.OK, string body = "{}") => new ExtractCvKeywordTests.FactoryStub(new HttpClient(new ExtractCvKeywordTests.CountingHandler(status, body)));
}
